code.cpp:
class Solution {
public:
    int sumOfUnique(vector<int>& nums) {
        int cnt[101] = {0};
        for (int x : nums) cnt[x]++;
        int sum = 0;
        for (int v = 1; v <= 100; ++v) {
            if (cnt[v] == 1) sum += v;
        }
        return sum;
    }
};
